class BytesIOCopy:
    """Mimic ``io.BytesIO`` while backed by a real file, so that the
    written stream is also copied to another stream and can be used as
    the target of e.g. ``subprocess.run(stdout=...)``, which requires a
    stream with a real file descriptor.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3.2
        Backed by a real file so it has a usable ``fileno()``.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file: t.BinaryIO = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

